insert into public.tools (
insert into public.services (title, slug, short_description, description_markdown, icon_name, price_label, features, process_steps, faq, is_featured, is_published, sort_order)
values
('Custom Tool Excel & Kế toán', 'custom-tool-excel-ke-toan', 'Thiết kế công cụ Excel/Windows theo nghiệp vụ kế toán riêng của doanh nghiệp.', 'Chúng tôi phân tích file mẫu, quy trình hiện tại và xây dựng tool giúp giảm thao tác lặp lại cho kế toán.', 'Table2', 'Liên hệ báo giá', '[{"text":"Chuẩn hóa dữ liệu đầu vào"},{"text":"Xuất báo cáo theo mẫu"},{"text":"Hỗ trợ bàn giao và chỉnh sửa"}]', '[{"text":"Khảo sát quy trình"},{"text":"Làm prototype"},{"text":"Bàn giao và hướng dẫn"}]', '[{"question":"Có nhận file mẫu bảo mật không?","answer":"Có, dữ liệu chỉ dùng để phân tích nghiệp vụ và có thể ký NDA nếu cần."}]', true, true, 10),
('Phát triển phần mềm Windows', 'phat-trien-phan-mem-windows', 'Xây dựng phần mềm EXE nội bộ, chạy ổn định trên Windows 10/11.', 'Dịch vụ phù hợp cho công cụ vận hành, nhập liệu, xử lý file và tích hợp API nội bộ.', 'MonitorCog', 'Liên hệ báo giá', '[{"text":"Giao diện dễ dùng"},{"text":"Cài đặt dạng EXE"},{"text":"Bảo trì sau bàn giao"}]', '[{"text":"Chốt phạm vi"},{"text":"Thiết kế UI"},{"text":"Phát triển và test"}]', '[]', true, true, 20),
('Tự động hóa quy trình RPA', 'tu-dong-hoa-quy-trinh-rpa', 'Tự động hóa thao tác lặp lại trên trình duyệt, phần mềm và file nội bộ.', 'Giảm thời gian nhập liệu, copy paste và kiểm tra thủ công bằng bot RPA theo kịch bản.', 'Bot', 'Liên hệ báo giá', '[{"text":"Tự động đăng nhập và nhập liệu"},{"text":"Theo dõi lỗi rõ ràng"},{"text":"Có log vận hành"}]', '[{"text":"Ghi nhận thao tác"},{"text":"Xây dựng bot"},{"text":"Chạy thử với dữ liệu thật"}]', '[]', true, true, 30),
('Xử lý và thu thập dữ liệu', 'xu-ly-va-thu-thap-du-lieu', 'Thu thập, làm sạch và xuất dữ liệu từ website, file hoặc API.', 'Giải pháp cho đội cần dữ liệu có cấu trúc phục vụ báo cáo, bán hàng hoặc vận hành.', 'DatabaseZap', 'Liên hệ báo giá', '[{"text":"Scraping có kiểm soát"},{"text":"Làm sạch dữ liệu"},{"text":"Xuất Excel/CSV/JSON"}]', '[{"text":"Xác định nguồn dữ liệu"},{"text":"Thiết kế bộ lọc"},{"text":"Bàn giao dữ liệu và tool"}]', '[]', false, true, 40),
('Hệ thống quản lý nội bộ', 'he-thong-quan-ly-noi-bo', 'Thiết kế hệ thống quản lý quy trình, khách hàng, đơn hàng hoặc kho nội bộ.', 'Xây dựng web app hoặc phần mềm nội bộ nhẹ, tập trung đúng quy trình doanh nghiệp.', 'BriefcaseBusiness', 'Liên hệ báo giá', '[{"text":"Phân quyền nội bộ"},{"text":"Báo cáo vận hành"},{"text":"Dữ liệu tập trung"}]', '[{"text":"Phân tích nghiệp vụ"},{"text":"Thiết kế màn hình"},{"text":"Triển khai từng giai đoạn"}]', '[]', false, true, 50),
('Tích hợp API và nền tảng', 'tich-hop-api-va-nen-tang', 'Kết nối phần mềm với sàn, CRM, kế toán, Zalo, Telegram hoặc hệ thống sẵn có.', 'Dịch vụ giúp dữ liệu đi đúng nơi, giảm nhập liệu lại và hạn chế sai sót.', 'Cable', 'Liên hệ báo giá', '[{"text":"Kết nối API"},{"text":"Đồng bộ dữ liệu"},{"text":"Cảnh báo lỗi tích hợp"}]', '[{"text":"Kiểm tra tài liệu API"},{"text":"Xây dựng connector"},{"text":"Theo dõi sau triển khai"}]', '[]', false, true, 60)
insert into public.content_blocks (page_key, section_key, title, content, sort_order, is_published)
values
('home', 'hero', 'Cửa hàng phần mềm', '{"description":"Các công cụ Windows giúp tự động hóa công việc, xử lý dữ liệu và tiết kiệm thời gian.","badges":["Phần mềm chính chủ","Cập nhật miễn phí","Hỗ trợ tiếng Việt","Tư vấn triển khai"]}', 10, true),
('home', 'trust', 'Vì sao chọn ToolBox Việt', '{"items":["Giao diện rõ ràng, dễ dùng cho người Việt","Có thể tùy chỉnh theo quy trình thật","Dữ liệu và bảo mật được ưu tiên","Hỗ trợ sau bàn giao"]}', 20, true),
('services', 'hero', 'Dịch vụ & Giải pháp Tùy chỉnh', '{"description":"Giải pháp tự động hóa tùy chỉnh và phát triển phần mềm chuyên biệt cho doanh nghiệp của bạn.","badges":["Thiết kế theo yêu cầu","Tối ưu quy trình","Hỗ trợ tận tâm"]}', 10, true),
('contact', 'copy', 'Liên hệ tư vấn', '{"description":"Để lại nhu cầu của bạn, đội ngũ kỹ thuật sẽ phản hồi với hướng triển khai phù hợp."}', 10, true),
('footer', 'links', 'Footer', '{"columns":[{"title":"Liên kết","links":["Cửa hàng","Dịch vụ","Chính sách bảo mật","Điều khoản sử dụng"]}]}', 10, true),
('privacy', 'main', 'Chính sách bảo mật', '{"body":"ToolBox Việt chỉ thu thập thông tin cần thiết để tư vấn, báo giá và hỗ trợ khách hàng. Chúng tôi không bán dữ liệu cá nhân cho bên thứ ba."}', 10, true),
('terms', 'main', 'Điều khoản sử dụng', '{"body":"Khi sử dụng website, bạn đồng ý cung cấp thông tin chính xác khi gửi yêu cầu tư vấn và tuân thủ điều khoản sử dụng phần mềm được bàn giao."}', 10, true)
