values
((select id from category_map where slug='hinh-anh'), 'Batch Image Studio', 'batch-image-studio', 'Xử lý ảnh hàng loạt: nén, đổi định dạng, resize và đóng dấu trong vài giây.', 'Batch Image Studio dành cho shop online, designer và đội vận hành cần xử lý nhiều ảnh mỗi ngày. Công cụ chạy trên Windows, tối ưu thao tác kéo thả và preset.', 'fixed', 599000, 799000, '2.4.0', 'Bản quyền trọn đời cho 1 máy', array['Windows 10','Windows 11'], '84 MB', array['Tiếng Việt','English'], 'Bán chạy', 'Yêu cầu báo giá', 'contact', '[{"text":"Resize, watermark và convert hàng loạt"},{"text":"Preset cho sàn thương mại điện tử"},{"text":"Xuất log xử lý sau mỗi phiên"}]', '[{"text":"Windows 10/11 64-bit"},{"text":"RAM tối thiểu 4GB"},{"text":"Dung lượng trống 300MB"}]', '[{"text":"2.4.0: Thêm preset WebP và tối ưu tốc độ nén"}]', '[{"question":"Có cần Internet để chạy không?","answer":"Không, các thao tác chính chạy offline trên máy Windows."}]', 'Batch Image Studio - Tool xử lý ảnh hàng loạt', 'Nén, resize, watermark và chuyển đổi ảnh hàng loạt trên Windows.', true, true, 10, now()),
